sp_widget.client_script:
function ($rootScope, $scope) {
  var c = this;

  c.selectItem = function (idx) {
    if (!c.data || !c.data.notes || !c.data.notes[idx]) return;

    var id = (c.data.notes[idx].sys_id || '') + '';
    console.log('[Notes List] EMIT selectNote id=', id);
    $rootScope.noteID = id;
    $rootScope.$emit('selectNote', id);
  };

  // Listen for updates from the Notes Body widget
  $rootScope.$on('noteUpdated', function(event, updatedNote) {
    console.log('[Notes List] Received noteUpdated event:', updatedNote);

    if (!c.data || !c.data.notes) return;

    // Update the note in the list without reload
    c.data.notes.forEach(function(n) {
      if (n.sys_id === updatedNote.noteID) {
        n.title = updatedNote.title;
        n.note  = updatedNote.body;
      }
    });
  });
}

sp_widget.script:
(function () {
  // create an array to populate with notes
  data.notes = [];

  var noteGR = new GlideRecord('x_snc_createnotes_note');
  noteGR.addQuery('user', gs.getUser().getID()); // current user’s notes
  noteGR.orderByDesc('sys_created_on');          // newest first
  noteGR.query();

  while (noteGR.next()) {
    var noteObj = {};
    // use Service Portal helper to get display values
    $sp.getRecordDisplayValues(noteObj, noteGR, 'number,title,sys_id');
    // first 20 chars of the description/body
    var body = noteGR.getValue('note') || '';
    noteObj.note = body.slice(0, 20);
    // push to the list
    data.notes.push(noteObj);
  }
})();
